/// <summary>
///     Data Controller class for <c>AVASalesOrderDelegationReport</c> SSRS report
/// </summary>
/// <remarks>
///     This is the Controller class for the <c>AVASalesOrderDelegationReport</c> SSRS Report.
/// </remarks>
internal final class AVASalesOrderDelegationReportController extends  SrsReportRunController
{
    Args        clsArgs;
    SalesTable  clsSalesTable;
    boolean     clsPreviewMode;

}

Method.Source:
/// <summary>
///    AVA <c>construct</c> method.
/// </summary>
/// <returns>
///    <c>AVASalesOrderDelegationReportController</c> as return value
/// </returns>
public static AVASalesOrderDelegationReportController construct()
{
    return new AVASalesOrderDelegationReportController();
}

/// <summary>
///    AVA <c>parmArgs</c> method.
/// </summary>
/// <param name="_parmValue">
///    <c>RefRecId</c> as type
/// </param>
/// <returns>
///    <c>Args</c> as return value
/// </returns>
public Args parmArgs(Args _parmValue = clsArgs)
{
    clsArgs = _parmValue;

    return clsArgs;
}

/// <summary>
///    AVA <c>parmSalesTable</c> method.
/// </summary>
/// <param name="_parmValue">
///    <c>SalesTable</c> as type
/// </param>
/// <returns>
///    <c>SalesTable</c> as return value
/// </returns>
public SalesTable parmSalesTable(SalesTable _parmValue = clsSalesTable)
{
    clsSalesTable = _parmValue;

    return clsSalesTable;
}

/// <summary>
///    AVA <c>main</c> method.
/// </summary>
/// <param name="_args">
///    <c>Args</c> as type
/// </param>
public static void main(Args _args)
{
    AVASalesOrderDelegationReportController controller;

    controller = AVASalesOrderDelegationReportController::newFromArgs(_args);

    controller.parmReportName(ssrsReportStr(AVASalesOrderDelegationReport, Report));
    controller.parmDialogCaption("@NDX:NXADelegationReport");
    controller.startOperation();
}

/// <summary>
///    AVA <c>prePromptModifyContract</c> method.
/// </summary>
protected void prePromptModifyContract()
{
    AVASalesOrderDelegationReportContract contract;

    clsPreviewMode = false;

    contract = this.parmReportContract().parmRdpContract();
    contract.parmSalesTableRefRecId(clsSalesTable.RecId);
    contract.parmSalesId(clsSalesTable.SalesId);
    contract.parmPrintMode(SalesTableMode::Simple);

    // Set the target print destination to Screen if we are previewing the report.
    if(this.parmArgs())
    {
        if(this.parmArgs().menuItemName() == menuItemActionStr(AVASalesOrderDelegationReportActionPreview))
        {
            clsPreviewMode = true;
        }
        else if(this.parmArgs().menuItemName() == menuItemActionStr(AVASalesOrderDelegationReportAction))
        {
            clsPreviewMode = false;
        }
        else if(this.parmArgs().menuItemName() == menuItemOutputStr(AVASalesOrderDelegationReportOutput))
        {
            clsPreviewMode = false;
        }
    }

    if (clsPreviewMode)
    {
        this.parmReportContract().parmPrintSettings().printMediumType(SRSPrintMediumType::Screen);
    }
    else
    //if(this.parmReportContract().parmPrintSettings().printMediumType() == SRSPrintMediumType::Email)
    {
        SRSPrintDestinationSettings locSRSPrintDestinationSettings;
        KCS_KAOReportMailLayout     locKCS_KAOReportMailLayout;
        SysEmailTable               locSysEmailTable;
        AVAPCMEmailSetup            locAVAPCMEmailSetup;
        SrsReportDataContract       locSrsReportDataContract;
        SrsReportEMailDataContract	locSrsReportEMailDataContract;
        str                         locSrsReportEMailDataContractSubject;
        AVAPCMEmailFormatter        locAVAPCMEmailFormatter;
        SysEmailMessageTable        locSysEmailMessageTable;
        str                         locAttachmentFileName;
        str                         locEmailFrom;
        str                         locEmailTo;
        str                         locEmailSubject;
        str                         locEmailBody;
        InventSite                  locInventSite;
        SRSReportFileFormat         locSRSReportFileFormat;

        RefTableId                  locRefTableId;
        RefRecId                    locRefRecId;
        SalesTable                  locSalesTableTmp;
        CustTable                   locCustTableTmp;

        AVASalesOrderDelegationReportContract locAVASalesOrderDelegationReportContract;

        locKCS_KAOReportMailLayout              = KCS_KAOReportMailLayout::find('AVASalesOrderDelegationReport'); //ssrsReportStr(AVASalesOrderDelegationReport, Report));
        locSysEmailTable                        = SysEmailTable::find(locKCS_KAOReportMailLayout.EmailId);
        locAVAPCMEmailSetup                     = AVAPCMEmailSetup::find(AVASalesParameters::find().EmailSetupId);

        locSrsReportDataContract                = this.parmReportContract();
        locSRSPrintDestinationSettings          = locSrsReportDataContract.parmPrintSettings();
        locAVAPCMEmailFormatter                 = AVAPCMEmailFormatter::construct(locSrsReportDataContract);

        locSrsReportEMailDataContract           = locSRSPrintDestinationSettings.parmEMailContract();
        locSrsReportEMailDataContractSubject    = locSrsReportEMailDataContract.parmSubject();

        //Load the message Table
        locSysEmailMessageTable                 = SysEmailMessageTable::find(   locKCS_KAOReportMailLayout.EmailId,
                                                                                locSrsReportDataContract.parmRdlContract().parmLanguageId()    );
        if (!locSysEmailMessageTable)
        {
            //Try finding the message using the default language
            locSysEmailMessageTable = SysEmailMessageTable::find(locKCS_KAOReportMailLayout.EmailId, locSysEmailTable.DefaultLanguage);
        }
        if (!locSysEmailMessageTable)
        {
            throw error(strfmt("@AVAPTC:MessageNotFound", locKCS_KAOReportMailLayout.EmailId));
        }

        //Set initial file name
        locAttachmentFileName   = locAVAPCMEmailSetup.Filename;
        locSRSReportFileFormat  = SRSReportFileFormat::PDF;
        //Set initial email values
        locEmailFrom            = locSysEmailTable.SenderAddr;
        locEmailTo              = '';                               
        locEmailSubject         = locSysEmailMessageTable.Subject;
        locEmailBody            = locSysEmailMessageTable.Mail;

        // Determine if we format the message or not.
        if (locAVAPCMEmailFormatter.hasContract())
        {
            locAVAPCMEmailFormatter.setCommon();

            locAttachmentFileName = locAVAPCMEmailFormatter.fillVariables(locAttachmentFileName, locSysEmailMessageTable.LanguageId);
            //Replace variables on the subject and body
            locEmailSubject         = locAVAPCMEmailFormatter.fillVariables(locEmailSubject, locSysEmailMessageTable.LanguageId);
            locEmailBody            = locAVAPCMEmailFormatter.fillVariables(locEmailBody, locSysEmailMessageTable.LanguageId);
            /*
            // CustTable variables
            locRefTableId           = locAVAPCMEmailFormatter.parmRefTableId();
            locRefRecId             = locAVAPCMEmailFormatter.parmRefRecId();
            if(locRefTableId == tableNum(SalesTable))
            {
                locSalesTableTmp    = SalesTable::findRecId(locRefRecId);
            }
            locCustTableTmp         = locAVAPCMEmailFormatter.parmClsCustTable();
            if(locCustTableTmp.RecId)
            {
                locAVAPCMEmailFormatter.parmRefTableId(locCustTableTmp.TableId);
                locAVAPCMEmailFormatter.parmRefRecId(locCustTableTmp.RecId);
                locAVAPCMEmailFormatter.setCommon();
                //Replace variables on the subject and body
                locAttachmentFileName   = locAVAPCMEmailFormatter.fillVariables(locAttachmentFileName, locSysEmailMessageTable.LanguageId);
                locEmailSubject         = locAVAPCMEmailFormatter.fillVariables(locEmailSubject, locSysEmailMessageTable.LanguageId);
                locEmailBody            = locAVAPCMEmailFormatter.fillVariables(locEmailBody, locSysEmailMessageTable.LanguageId);
            }
            locAVAPCMEmailFormatter.parmRefTableId(locRefTableId);
            locAVAPCMEmailFormatter.parmRefRecId(locRefRecId);
            locAVAPCMEmailFormatter.setCommon();
            */
            locSrsReportEMailDataContract.parmSubject(locEmailSubject);
            locSrsReportEMailDataContract.parmBody(locEmailBody);
        }
        else
        {
            //Variable replacement not supported, but still sending an email.
            locSrsReportEMailDataContract.parmSubject(locEmailSubject);
            locSrsReportEMailDataContract.parmBody(locEmailBody);
        }

        locInventSite = InventSite::find(clsSalesTable.InventSiteId);
        if(locInventSite.AVAAgentSite)
        {
            locEmailTo              = locInventSite.AVAEmailAgent;
        }
        locSrsReportEMailDataContract.parmTo(locEmailTo);
        locSrsReportEMailDataContract.parmAttachmentFileFormat(locSRSReportFileFormat);

        locSRSPrintDestinationSettings.emailTo(locEmailTo);
        locSRSPrintDestinationSettings.emailSubject(locEmailSubject);
        locSRSPrintDestinationSettings.emailbody(locEmailBody);
        locSRSPrintDestinationSettings.emailAttachmentFileFormat(locSRSReportFileFormat);

        locSRSPrintDestinationSettings.parmAVAPCMEmailSetupIdReplacement(locAVAPCMEmailSetup.EmailSetupId);
        locSRSPrintDestinationSettings.parmAVAPCMEmailSetupReplacement(locAVAPCMEmailSetup);
        locSRSPrintDestinationSettings.parmAVAPCMEmailFormatter(locAVAPCMEmailFormatter);

        if(locSrsReportDataContract.parmRdpContract() is AVASalesOrderDelegationReportContract)
        {
            locAVASalesOrderDelegationReportContract = locSrsReportDataContract.parmRdpContract();
        }
        locSRSPrintDestinationSettings.parmAVASalesOrderDelegationReportContract(locAVASalesOrderDelegationReportContract);

        this.parmReportContract().parmPrintSettings().printMediumType(SRSPrintMediumType::Email);
   }
    /*
    else
    //if(this.parmReportContract().parmPrintSettings().printMediumType() == SRSPrintMediumType::Email)
    {
        SRSPrintDestinationSettings locSRSPrintDestinationSettings;
        KCS_KAOReportMailLayout     locKCS_KAOReportMailLayout      = KCS_KAOReportMailLayout::find(ssrsReportStr(AVASalesOrderDelegationReport, Report));
        SysEmailTable               locSysEmailTable                = SysEmailTable::find(locKCS_KAOReportMailLayout.EmailId);
        SrsReportEMailDataContract	emailContract;
        str                         emailContractSubject;

        locSRSPrintDestinationSettings = this.parmReportContract().parmPrintSettings();
        locSRSPrintDestinationSettings.emailAttachmentFileFormat(SRSReportFileFormat::PDF);
        locSRSPrintDestinationSettings.emailSubject('');

        emailContract           = locSRSPrintDestinationSettings.parmEMailContract();
        emailContractSubject    = emailContract.parmSubject();

        InventSite locInventSite = InventSite::find(clsSalesTable.InventSiteId);
        if(locInventSite.AVAAgentSite)
        {
            locSRSPrintDestinationSettings.emailTo(locInventSite.AVAEmailAgent);
        }
    }
    */

    // Don't show the report dialog if Preview
    // and don't save to SysLastValue either.
    this.parmShowDialog(!clsPreviewMode);
    this.parmLoadFromSysLastValue(!clsPreviewMode);
}

/// <summary>
///    AVA <c>newFromArgs</c> method.
/// </summary>
/// <param name="_args">
///    <c>Args</c> as type
/// </param>
/// <returns>
///    <c>AVASalesOrderDelegationReportController</c> as return value
/// </returns>
public static AVASalesOrderDelegationReportController newFromArgs(Args _args)
{
    AVASalesOrderDelegationReportController locController;
    Common                                  locCommon;
    SalesTable                              locSalesTable;

    //controller = new AVASalesOrderDelegationReportController();
    locController = AVASalesOrderDelegationReportController::construct();
    locController.parmArgs(_args);
    locController.parmLoadFromSysLastValue(false);

    if(_args)
    {
        if(_args.record().RecId)
        {
            locCommon = _args.record();
            if(     locCommon.RecId
                &&  locCommon.TableId == tableNum(SalesTable))
            {
                locSalesTable = locCommon;
                locController.parmSalesTable(locSalesTable);
            }
        }
    }

    return locController;
}
